 update public.hr_roles set work_content=coalesce(work_content,'{}')||'{"interview_questionnaire_draft":{"version":1,"revision":1,"status":"draft","origin":"propuesta basada en contenido verificado de la plaza","review_note":"Propuesta automática pendiente de revisión y aprobación. No activa en entrevistas.","questions":[{"id":"iq_b1d97ac2bbc66eb8","section":"Recepción del cliente","text":"Un cliente solicita un servicio, pero faltan materiales y no están claros los entregables. ¿Qué preguntarías y registrarías antes de comprometer una fecha?","help":"Solicitar pasos concretos, criterios y un ejemplo; contrastar con las responsabilidades vigentes de la plaza.","type":"text","required":true,"options":[],"source":{"path":"work_content.custom.atencion-cliente","sha256":"d4a6fb3f9ad14770a32e08daa84c20c8971b3a339889b9311cbc5b347116b56e"}},{"id":"iq_f8d9bc4880bfcc87","section":"Prioridades","text":"Tienes una entrega próxima, materiales pendientes de otro cliente y un especialista bloqueado. ¿Cómo determinarías el orden de atención y qué elevarías al Jefe de Área?","help":"Solicitar pasos concretos, criterios y un ejemplo; contrastar con las responsabilidades vigentes de la plaza.","type":"text","required":true,"options":[],"source":{"path":"work_content.custom.prioridades","sha256":"c7877210e300efb64ad25dd643b13047379377a16c199c21342a06bff87ad483"}},{"id":"iq_f9d49ee999b6183e","section":"Coordinación","text":"Un especialista comunica que no llegará al plazo acordado. ¿Qué comprobarías, qué alternativas prepararías y quién debe aprobar cambios del calendario?","help":"Solicitar pasos concretos, criterios y un ejemplo; contrastar con las responsabilidades vigentes de la plaza.","type":"text","required":true,"options":[],"source":{"path":"work_content.custom.coordinar-especialistas","sha256":"ecf052b3bc6dda81eca9b5782bbadb2ae6cb0124f107dd8b10ba9e73d972f8cf"}},{"id":"iq_3e3216bdfcfaf049","section":"Límites comerciales","text":"Un cliente pide un descuento y un entregable adi